
CREATE TABLE IF NOT EXISTS branches(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT DEFAULT '', phone TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','salesman','cashier','technician')), active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('customer','supplier')), name TEXT NOT NULL, phone TEXT DEFAULT '', address TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, sku TEXT UNIQUE, barcode TEXT UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, brand TEXT DEFAULT '', model TEXT DEFAULT '', variant TEXT DEFAULT '', color TEXT DEFAULT '', storage TEXT DEFAULT '', condition TEXT DEFAULT 'new', compatible_models TEXT DEFAULT '', cost REAL NOT NULL DEFAULT 0 CHECK(cost>=0), price REAL NOT NULL DEFAULT 0 CHECK(price>=0), min_price REAL NOT NULL DEFAULT 0 CHECK(min_price>=0), quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), reorder_level INTEGER NOT NULL DEFAULT 0, warranty_days INTEGER NOT NULL DEFAULT 0, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS phones(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), imei1 TEXT NOT NULL UNIQUE, imei2 TEXT UNIQUE, pta_status TEXT DEFAULT 'unknown', condition_grade TEXT DEFAULT '', checklist TEXT DEFAULT '{}', box_included INTEGER DEFAULT 0, charger_included INTEGER DEFAULT 0, purchase_cost REAL NOT NULL DEFAULT 0, prep_cost REAL NOT NULL DEFAULT 0, supplier_id INTEGER REFERENCES contacts(id), purchase_date TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','sold','returned','supplier_return')), sale_id INTEGER, notes TEXT DEFAULT '', branch_id INTEGER DEFAULT 1 REFERENCES branches(id));
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY, supplier_id INTEGER REFERENCES contacts(id), reference TEXT DEFAULT '', date TEXT DEFAULT CURRENT_TIMESTAMP, total REAL NOT NULL, paid REAL NOT NULL DEFAULT 0, payment_method TEXT DEFAULT 'cash', notes TEXT DEFAULT '', branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_lines(id INTEGER PRIMARY KEY, purchase_id INTEGER REFERENCES purchases(id), product_id INTEGER REFERENCES products(id), phone_id INTEGER REFERENCES phones(id), quantity INTEGER NOT NULL, unit_cost REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, invoice_no TEXT NOT NULL UNIQUE, customer_id INTEGER REFERENCES contacts(id), date TEXT DEFAULT CURRENT_TIMESTAMP, subtotal REAL NOT NULL, discount REAL DEFAULT 0, total REAL NOT NULL, paid REAL DEFAULT 0, status TEXT DEFAULT 'completed', trade_in_phone_id INTEGER REFERENCES phones(id), trade_in_value REAL DEFAULT 0, notes TEXT DEFAULT '', branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sale_lines(id INTEGER PRIMARY KEY, sale_id INTEGER REFERENCES sales(id), product_id INTEGER REFERENCES products(id), phone_id INTEGER REFERENCES phones(id), description TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, unit_cost REAL NOT NULL DEFAULT 0, warranty_days INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, direction TEXT NOT NULL, contact_id INTEGER REFERENCES contacts(id), sale_id INTEGER REFERENCES sales(id), purchase_id INTEGER REFERENCES purchases(id), repair_id INTEGER, method TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>0), date TEXT DEFAULT CURRENT_TIMESTAMP, notes TEXT DEFAULT '', branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repairs(id INTEGER PRIMARY KEY, job_no TEXT NOT NULL UNIQUE, customer_id INTEGER REFERENCES contacts(id), model TEXT NOT NULL, imei TEXT DEFAULT '', fault TEXT NOT NULL, condition_notes TEXT DEFAULT '', received_accessories TEXT DEFAULT '', expected_date TEXT DEFAULT '', technician_id INTEGER REFERENCES users(id), status TEXT DEFAULT 'Received', labor_charge REAL DEFAULT 0, other_cost REAL DEFAULT 0, parts_cost REAL DEFAULT 0, paid REAL DEFAULT 0, date TEXT DEFAULT CURRENT_TIMESTAMP, delivered_at TEXT, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_parts(id INTEGER PRIMARY KEY, repair_id INTEGER REFERENCES repairs(id), product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL, unit_cost REAL NOT NULL);
CREATE TABLE IF NOT EXISTS warranty_claims(id INTEGER PRIMARY KEY, sale_id INTEGER REFERENCES sales(id), phone_id INTEGER REFERENCES phones(id), issue TEXT NOT NULL, action TEXT DEFAULT '', result TEXT DEFAULT '', status TEXT DEFAULT 'open', date TEXT DEFAULT CURRENT_TIMESTAMP, closed_at TEXT, created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS installments(id INTEGER PRIMARY KEY, sale_id INTEGER REFERENCES sales(id), due_date TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>0), paid REAL DEFAULT 0, paid_at TEXT);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY, category TEXT NOT NULL, description TEXT DEFAULT '', amount REAL NOT NULL CHECK(amount>0), method TEXT DEFAULT 'cash', date TEXT DEFAULT CURRENT_TIMESTAMP, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cash_sessions(id INTEGER PRIMARY KEY, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), opened_at TEXT DEFAULT CURRENT_TIMESTAMP, closed_at TEXT, opening REAL NOT NULL, actual_closing REAL, expected_closing REAL, opened_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS drawings(id INTEGER PRIMARY KEY, amount REAL NOT NULL CHECK(amount>0), notes TEXT DEFAULT '', date TEXT DEFAULT CURRENT_TIMESTAMP, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY, product_id INTEGER REFERENCES products(id), phone_id INTEGER REFERENCES phones(id), delta INTEGER NOT NULL, reason TEXT NOT NULL, reference_id INTEGER, date TEXT DEFAULT CURRENT_TIMESTAMP, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS market_rates(id INTEGER PRIMARY KEY, product_id INTEGER REFERENCES products(id), buy_rate REAL NOT NULL, sell_rate REAL NOT NULL, date TEXT DEFAULT CURRENT_TIMESTAMP, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, details TEXT DEFAULT '{}', date TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS used_purchases(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES contacts(id), phone_id INTEGER NOT NULL REFERENCES phones(id), agreed_price REAL NOT NULL, paid REAL NOT NULL DEFAULT 0, testing_notes TEXT DEFAULT '', date TEXT DEFAULT CURRENT_TIMESTAMP, branch_id INTEGER DEFAULT 1 REFERENCES branches(id), created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_returns(id INTEGER PRIMARY KEY, purchase_line_id INTEGER NOT NULL REFERENCES purchase_lines(id), quantity INTEGER NOT NULL, refund REAL NOT NULL, reason TEXT DEFAULT '', date TEXT DEFAULT CURRENT_TIMESTAMP, created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sale_returns(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), sale_line_id INTEGER NOT NULL REFERENCES sale_lines(id), quantity INTEGER NOT NULL CHECK(quantity>0), amount REAL NOT NULL CHECK(amount>=0), refund REAL NOT NULL CHECK(refund>=0), refund_method TEXT NOT NULL DEFAULT 'cash', restock INTEGER NOT NULL DEFAULT 1, reason TEXT NOT NULL DEFAULT '', date TEXT DEFAULT CURRENT_TIMESTAMP, created_by INTEGER REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_sale_returns_sale ON sale_returns(sale_id);
CREATE TABLE IF NOT EXISTS backup_preferences(id INTEGER PRIMARY KEY CHECK(id=1), destination TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 0, interval_hours INTEGER NOT NULL DEFAULT 24, last_success TEXT, last_error TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO backup_preferences(id) VALUES(1);
CREATE TABLE IF NOT EXISTS price_history(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), old_cost REAL, new_cost REAL, old_price REAL, new_price REAL, date TEXT DEFAULT CURRENT_TIMESTAMP, changed_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS shop_settings(id INTEGER PRIMARY KEY CHECK(id=1), shop_name TEXT NOT NULL, tagline TEXT NOT NULL, logo_data TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', receipt_footer TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO shop_settings(id,shop_name,tagline,receipt_footer) VALUES(1,'Mobile Shop','Desktop ERP','Thank you for shopping with us.');
INSERT OR IGNORE INTO branches(id,name) VALUES(1,'Main branch');
CREATE INDEX IF NOT EXISTS idx_phones_status ON phones(status);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(date);
CREATE INDEX IF NOT EXISTS idx_payments_contact ON payments(contact_id);
CREATE TABLE IF NOT EXISTS recovery_keys(id INTEGER PRIMARY KEY CHECK(id=1), recovery_key_hash TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
